-- Maktabah Ruhayn commerce schema for Cloudflare D1 (SQLite).
--
-- Conventions
--   ids         text, generated by the application (ULID-style, sortable)
--   money       integer minor units (cents) in the row's currency, never float
--   timestamps  text, ISO-8601 UTC, which sorts correctly as text
--   booleans    integer 0/1
--
-- Regions stay in code (packages/shared CURRENCY_REGIONS): they are static
-- configuration, not data an admin edits. Only the FX rates they depend on
-- live here. Prices are stored per currency where they are set explicitly,
-- and derived from the base currency through fx_rate everywhere else.

-- ---------------------------------------------------------------- catalogue

CREATE TABLE product (
  id                  TEXT PRIMARY KEY,
  product_number      INTEGER UNIQUE,
  handle              TEXT NOT NULL UNIQUE,
  title               TEXT NOT NULL,
  subtitle            TEXT,
  description_html    TEXT NOT NULL DEFAULT '',
  status              TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')),
  publish_at          TEXT,
  thumbnail           TEXT,
  unit                TEXT NOT NULL DEFAULT 'item',
  product_type        TEXT NOT NULL DEFAULT 'standard' CHECK (product_type IN ('standard','bundle')),
  delivery_type       TEXT NOT NULL DEFAULT 'physical' CHECK (delivery_type IN ('physical','digital')),
  primary_category_id TEXT,
  option_title        TEXT NOT NULL DEFAULT 'Format',
  option_display      TEXT NOT NULL DEFAULT 'buttons' CHECK (option_display IN ('buttons','dropdown')),
  shipping_size       TEXT NOT NULL DEFAULT 'small',
  pages               INTEGER,
  series              TEXT,
  release_date        TEXT,
  preorder            INTEGER NOT NULL DEFAULT 0,
  bookseller_note     TEXT,
  author_bio          TEXT,
  editorial_reviews   TEXT NOT NULL DEFAULT '[]',   -- json: [{quote,source}]
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at          TEXT
);
CREATE INDEX product_status_idx  ON product (status, deleted_at);
CREATE INDEX product_updated_idx ON product (updated_at DESC);

CREATE TABLE product_image (
  id         TEXT PRIMARY KEY,
  product_id TEXT NOT NULL REFERENCES product (id) ON DELETE CASCADE,
  url        TEXT NOT NULL,
  rank       INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX product_image_product_idx ON product_image (product_id, rank);

-- One Book row per product: the bibliographic detail the storefront shows.
CREATE TABLE book (
  product_id          TEXT PRIMARY KEY REFERENCES product (id) ON DELETE CASCADE,
  title_arabic        TEXT,
  author              TEXT,
  translator          TEXT,
  commentator_tahqeeq TEXT,
  publisher           TEXT,
  binding_type        TEXT,
  script_type         TEXT,
  language            TEXT,
  volume_count        INTEGER,
  isbn_10             TEXT,
  isbn_13             TEXT,
  sample_pdf_url      TEXT
);
-- Unique among live books, so a deleted book's ISBN can be reused.
CREATE UNIQUE INDEX book_isbn_13_idx ON book (isbn_13) WHERE isbn_13 IS NOT NULL;
CREATE UNIQUE INDEX book_isbn_10_idx ON book (isbn_10) WHERE isbn_10 IS NOT NULL;
CREATE INDEX book_author_idx    ON book (author);
CREATE INDEX book_publisher_idx ON book (publisher);

CREATE TABLE category (
  id        TEXT PRIMARY KEY,
  handle    TEXT NOT NULL UNIQUE,
  name      TEXT NOT NULL,
  parent_id TEXT REFERENCES category (id) ON DELETE SET NULL,
  rank      INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX category_parent_idx ON category (parent_id, rank);

CREATE TABLE product_category (
  product_id  TEXT NOT NULL REFERENCES product (id) ON DELETE CASCADE,
  category_id TEXT NOT NULL REFERENCES category (id) ON DELETE CASCADE,
  PRIMARY KEY (product_id, category_id)
);
CREATE INDEX product_category_category_idx ON product_category (category_id);

-- Merchandising tags (bestseller, new-release, coming-soon, staff-pick).
CREATE TABLE product_tag (
  product_id TEXT NOT NULL REFERENCES product (id) ON DELETE CASCADE,
  value      TEXT NOT NULL,
  PRIMARY KEY (product_id, value)
);
CREATE INDEX product_tag_value_idx ON product_tag (value);

-- A bundle product sells other products together.
CREATE TABLE bundle_item (
  bundle_id  TEXT NOT NULL REFERENCES product (id) ON DELETE CASCADE,
  product_id TEXT NOT NULL REFERENCES product (id) ON DELETE CASCADE,
  quantity   INTEGER NOT NULL DEFAULT 1,
  rank       INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (bundle_id, product_id)
);

-- --------------------------------------------------------------- variants

CREATE TABLE variant (
  id                  TEXT PRIMARY KEY,
  product_id          TEXT NOT NULL REFERENCES product (id) ON DELETE CASCADE,
  title               TEXT NOT NULL,
  option_value        TEXT NOT NULL,
  system_sku          TEXT NOT NULL UNIQUE,
  custom_sku          TEXT,
  manage_inventory    INTEGER NOT NULL DEFAULT 1,
  allow_backorder     INTEGER NOT NULL DEFAULT 0,
  low_stock_threshold INTEGER,
  cost_minor          INTEGER,
  weight_g            INTEGER,
  length_cm           INTEGER,
  width_cm            INTEGER,
  height_cm           INTEGER,
  rank                INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX variant_product_idx ON variant (product_id, rank);

-- A price that is set explicitly. Anything not listed here is converted from
-- the base currency with fx_rate at read time, so adding a currency needs no
-- backfill. `kind` separates the normal price from the struck-through one.
CREATE TABLE variant_price (
  variant_id    TEXT NOT NULL REFERENCES variant (id) ON DELETE CASCADE,
  currency_code TEXT NOT NULL,
  kind          TEXT NOT NULL DEFAULT 'base' CHECK (kind IN ('base','sale')),
  amount_minor  INTEGER NOT NULL,
  price_list_id TEXT REFERENCES price_list (id) ON DELETE CASCADE,
  PRIMARY KEY (variant_id, currency_code, kind)
);

-- Scheduled sale windows. A price row pointing at a list only applies while
-- the list is active.
CREATE TABLE price_list (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL,
  starts_at  TEXT,
  ends_at    TEXT,
  is_active  INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE fx_rate (
  currency_code TEXT PRIMARY KEY,
  rate          REAL NOT NULL,          -- units of this currency per base unit
  fetched_at    TEXT NOT NULL
);

-- --------------------------------------------------------------- inventory

CREATE TABLE stock_location (
  id   TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE inventory_level (
  variant_id        TEXT NOT NULL REFERENCES variant (id) ON DELETE CASCADE,
  location_id       TEXT NOT NULL REFERENCES stock_location (id) ON DELETE CASCADE,
  stocked_quantity  INTEGER NOT NULL DEFAULT 0,
  reserved_quantity INTEGER NOT NULL DEFAULT 0,
  -- Bumped on every write so checkout can detect a concurrent change: D1 has
  -- no interactive transactions, so stock is claimed with a compare-and-set
  -- rather than a lock.
  version           INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (variant_id, location_id)
);

-- ------------------------------------------------------------- customers

CREATE TABLE customer (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE COLLATE NOCASE,
  password_hash TEXT,                  -- null for guest-created records
  first_name    TEXT,
  last_name     TEXT,
  phone         TEXT,
  payment_pref  TEXT,                  -- 'mpesa' | 'card' | null
  mpesa_phone   TEXT,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE customer_address (
  id           TEXT PRIMARY KEY,
  customer_id  TEXT NOT NULL REFERENCES customer (id) ON DELETE CASCADE,
  first_name   TEXT,
  last_name    TEXT,
  address_1    TEXT,
  address_2    TEXT,
  city         TEXT,
  province     TEXT,
  postal_code  TEXT,
  country_code TEXT,
  phone        TEXT,
  is_default   INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX customer_address_customer_idx ON customer_address (customer_id);

-- ------------------------------------------------------------------ carts

CREATE TABLE cart (
  id                TEXT PRIMARY KEY,
  customer_id       TEXT REFERENCES customer (id) ON DELETE SET NULL,
  email             TEXT,
  currency_code     TEXT NOT NULL,
  country_code      TEXT,
  shipping_address  TEXT,              -- json
  billing_address   TEXT,              -- json
  shipping_option_id TEXT,
  shipping_total    INTEGER NOT NULL DEFAULT 0,
  promotion_code    TEXT,
  discount_total    INTEGER NOT NULL DEFAULT 0,
  gift_note         TEXT,
  completed_order_id TEXT,
  created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX cart_customer_idx ON cart (customer_id);
CREATE INDEX cart_updated_idx  ON cart (updated_at DESC);

CREATE TABLE cart_item (
  id               TEXT PRIMARY KEY,
  cart_id          TEXT NOT NULL REFERENCES cart (id) ON DELETE CASCADE,
  -- A book withdrawn from sale leaves the carts holding it, rather than
  -- blocking its own deletion or leaving a line pointing at nothing.
  variant_id       TEXT NOT NULL REFERENCES variant (id) ON DELETE CASCADE,
  quantity         INTEGER NOT NULL CHECK (quantity > 0),
  -- Snapshot: the cart keeps what the shopper was shown, so a later price
  -- change never silently alters a cart or an order.
  unit_price_minor INTEGER NOT NULL,
  title            TEXT NOT NULL,
  subtitle         TEXT,
  thumbnail        TEXT,
  UNIQUE (cart_id, variant_id)
);

-- ----------------------------------------------------------------- orders

CREATE TABLE "order" (
  id                 TEXT PRIMARY KEY,
  display_id         INTEGER NOT NULL UNIQUE,
  customer_id        TEXT REFERENCES customer (id) ON DELETE SET NULL,
  email              TEXT NOT NULL,
  currency_code      TEXT NOT NULL,
  subtotal_minor     INTEGER NOT NULL,
  discount_minor     INTEGER NOT NULL DEFAULT 0,
  shipping_minor     INTEGER NOT NULL DEFAULT 0,
  tax_minor          INTEGER NOT NULL DEFAULT 0,
  total_minor        INTEGER NOT NULL,
  status             TEXT NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending','completed','cancelled')),
  payment_status     TEXT NOT NULL DEFAULT 'awaiting'
                     CHECK (payment_status IN ('awaiting','authorized','captured','failed','refunded')),
  fulfillment_status TEXT NOT NULL DEFAULT 'not_fulfilled'
                     CHECK (fulfillment_status IN ('not_fulfilled','shipped','delivered','returned')),
  shipping_address   TEXT NOT NULL,    -- json snapshot
  billing_address    TEXT,             -- json snapshot
  shipping_method    TEXT,             -- json: {name, provider, amount_minor}
  promotion_code     TEXT,
  gift_note          TEXT,
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX order_customer_idx ON "order" (customer_id, created_at DESC);
CREATE INDEX order_created_idx  ON "order" (created_at DESC);

CREATE TABLE order_item (
  id               TEXT PRIMARY KEY,
  order_id         TEXT NOT NULL REFERENCES "order" (id) ON DELETE CASCADE,
  variant_id       TEXT,              -- kept nullable: a deleted book must not erase order history
  product_title    TEXT NOT NULL,
  variant_title    TEXT NOT NULL,
  sku              TEXT,
  thumbnail        TEXT,
  quantity         INTEGER NOT NULL,
  unit_price_minor INTEGER NOT NULL,
  total_minor      INTEGER NOT NULL
);
CREATE INDEX order_item_order_idx ON order_item (order_id);

CREATE TABLE payment (
  id            TEXT PRIMARY KEY,
  order_id      TEXT REFERENCES "order" (id) ON DELETE CASCADE,
  cart_id       TEXT,
  provider      TEXT NOT NULL CHECK (provider IN ('stripe','mpesa','manual')),
  status        TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending','authorized','captured','failed','cancelled','refunded')),
  amount_minor  INTEGER NOT NULL,
  currency_code TEXT NOT NULL,
  reference     TEXT,                 -- PaymentIntent id, M-Pesa receipt
  raw           TEXT,                 -- json: last provider payload
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX payment_order_idx     ON payment (order_id);
CREATE UNIQUE INDEX payment_ref_idx ON payment (provider, reference) WHERE reference IS NOT NULL;

CREATE TABLE shipment (
  id              TEXT PRIMARY KEY,
  order_id        TEXT NOT NULL REFERENCES "order" (id) ON DELETE CASCADE,
  provider        TEXT NOT NULL DEFAULT 'shippo',
  tracking_number TEXT,
  tracking_url    TEXT,
  label_url       TEXT,
  status          TEXT,
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX shipment_order_idx ON shipment (order_id);

-- Every external callback (Stripe, M-Pesa, Shippo) and every checkout writes
-- through this table first. D1 cannot hold a transaction open across the
-- reads and decisions a checkout makes, so replay safety is explicit.
CREATE TABLE idempotency_key (
  key        TEXT PRIMARY KEY,
  scope      TEXT NOT NULL,
  result     TEXT,                    -- json of the first successful outcome
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- ------------------------------------------------------------- promotions

CREATE TABLE promotion (
  id                 TEXT PRIMARY KEY,
  code               TEXT NOT NULL UNIQUE COLLATE NOCASE,
  description        TEXT,
  type               TEXT NOT NULL CHECK (type IN ('percentage','fixed','free_shipping')),
  value              INTEGER NOT NULL DEFAULT 0,  -- percent, or minor units of currency_code
  currency_code      TEXT,                        -- required for 'fixed'
  min_subtotal_minor INTEGER,
  starts_at          TEXT,
  ends_at            TEXT,
  usage_limit        INTEGER,
  used_count         INTEGER NOT NULL DEFAULT 0,
  is_active          INTEGER NOT NULL DEFAULT 1
);

-- --------------------------------------------------- shipping, reviews, etc

CREATE TABLE shipping_option (
  id              TEXT PRIMARY KEY,
  name            TEXT NOT NULL,
  provider        TEXT NOT NULL DEFAULT 'manual' CHECK (provider IN ('manual','shippo')),
  countries       TEXT NOT NULL DEFAULT '[]',  -- json: [] means every country
  amount_minor    INTEGER,                     -- null for live-rated (shippo)
  currency_code   TEXT,
  free_above_minor INTEGER,
  rank            INTEGER NOT NULL DEFAULT 0,
  is_active       INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE review (
  id          TEXT PRIMARY KEY,
  product_id  TEXT NOT NULL REFERENCES product (id) ON DELETE CASCADE,
  customer_id TEXT REFERENCES customer (id) ON DELETE SET NULL,
  author_name TEXT,
  rating      INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  title       TEXT,
  body        TEXT,
  status      TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX review_product_idx ON review (product_id, status);

CREATE TABLE newsletter_subscriber (
  id           TEXT PRIMARY KEY,
  email        TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name         TEXT,
  phone        TEXT,
  country_code TEXT,
  source       TEXT,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- One json document per section (business, theme, content, navigation, ...),
-- the same shape the admin edits today.
CREATE TABLE store_setting (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE email_log (
  id         TEXT PRIMARY KEY,
  template   TEXT NOT NULL,
  recipient  TEXT NOT NULL,
  subject    TEXT,
  status     TEXT NOT NULL DEFAULT 'sent' CHECK (status IN ('sent','failed')),
  error      TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX email_log_created_idx ON email_log (created_at DESC);

-- Admin-initiated M-Pesa STK pushes for phone and WhatsApp orders.
CREATE TABLE payment_request (
  id           TEXT PRIMARY KEY,
  phone        TEXT NOT NULL,
  amount_minor INTEGER NOT NULL,
  reference    TEXT NOT NULL,
  description  TEXT,
  order_id     TEXT REFERENCES "order" (id) ON DELETE SET NULL,
  status       TEXT NOT NULL DEFAULT 'pending'
               CHECK (status IN ('pending','paid','failed','cancelled')),
  checkout_id  TEXT,
  receipt      TEXT,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX payment_request_created_idx ON payment_request (created_at DESC);
